mapper.select:
SELECT h.id, h.class_id AS classId, COALESCE(NULLIF(h.class_name, ''), cg.name) AS className, h.teacher_id AS teacherId, h.teacher_name AS teacherName, h.title, h.content, h.due_date AS dueDate, h.publish_date AS publishDate, h.publisher, h.status, h.created_at AS createdAt, h.updated_at AS updatedAt FROM class_homework h LEFT JOIN class_group cg ON cg.id = h.class_id
AND h.class_id = #{classId}
AND (h.title LIKE CONCAT('%', #{keyword}, '%') OR h.content LIKE CONCAT('%', #{keyword}, '%'))
AND h.publish_date >= #{start} AND h.publish_date <= #{end}
ORDER BY h.publish_date DESC, h.id DESC
